"use client";

import { useCallback, useState, useRef, useEffect } from "react";
import {
  ReactFlow,
  ReactFlowProvider,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  addEdge,
  type Node,
  type Edge,
  type Connection,
  type OnConnect,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import Link from "next/link";
import { ArrowLeft, Check, CloudOff, Loader2 } from "lucide-react";
import { nodeTypes, type WorkflowNodeData } from "./workflow-node";
import { NodePalette } from "./node-palette";
import { NodeInspector } from "./node-inspector";
import { ExecutionPanel } from "./execution-panel";
import { api, ApiError, type Workflow, type WorkflowDefinition, type ExecutionStep } from "@/lib/api";

type FlowNode = Node<WorkflowNodeData>;

function toFlowNodes(def: WorkflowDefinition): FlowNode[] {
  return def.nodes.map((n) => ({
    id: n.id,
    type: "workflowNode",
    position: n.position,
    data: {
      label: (n.config.label as string) ?? n.type,
      nodeType: n.type as WorkflowNodeData["nodeType"],
      config: n.config,
    },
  }));
}

function toFlowEdges(def: WorkflowDefinition): Edge[] {
  return def.edges.map((e) => ({
    id: e.id,
    source: e.source,
    target: e.target,
    sourceHandle: e.source_handle,
    targetHandle: e.target_handle,
    animated: e.source_handle !== undefined,
  }));
}

function toDefinition(nodes: FlowNode[], edges: Edge[]): WorkflowDefinition {
  return {
    nodes: nodes.map((n) => ({
      id: n.id,
      type: n.data.nodeType,
      position: n.position,
      config: n.data.config,
    })),
    edges: edges.map((e) => ({
      id: e.id,
      source: e.source,
      target: e.target,
      source_handle: e.sourceHandle ?? undefined,
      target_handle: e.targetHandle ?? undefined,
    })),
  };
}

let nodeIdCounter = 0;
function newNodeId() {
  nodeIdCounter += 1;
  return `node_${Date.now()}_${nodeIdCounter}`;
}

type SaveState = "idle" | "dirty" | "saving" | "saved" | "error";

export function WorkflowEditor({ workflow }: { workflow: Workflow }) {
  return (
    <ReactFlowProvider>
      <EditorInner workflow={workflow} />
    </ReactFlowProvider>
  );
}

function EditorInner({ workflow }: { workflow: Workflow }) {
  const [nodes, setNodes, onNodesChange] = useNodesState<FlowNode>(toFlowNodes(workflow.definition));
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>(toFlowEdges(workflow.definition));
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [name, setName] = useState(workflow.name);
  const [saveState, setSaveState] = useState<SaveState>("idle");
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const selectedNode = nodes.find((n) => n.id === selectedNodeId) ?? null;

  // Autosave, debounced: every change marks the workflow dirty and schedules
  // a save a second later, coalescing rapid edits (dragging a node, typing
  // in the config textarea) into one PATCH instead of one per keystroke.
  const scheduleSave = useCallback(
    (nextNodes: FlowNode[], nextEdges: Edge[], nextName: string) => {
      setSaveState("dirty");
      if (saveTimer.current) clearTimeout(saveTimer.current);
      saveTimer.current = setTimeout(async () => {
        setSaveState("saving");
        try {
          await api.updateWorkflow(workflow.id, {
            name: nextName,
            definition: toDefinition(nextNodes, nextEdges),
          });
          setSaveState("saved");
        } catch (err) {
          setSaveState("error");
          console.error(err instanceof ApiError ? err.message : err);
        }
      }, 1000);
    },
    [workflow.id]
  );

  useEffect(() => {
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
    };
  }, []);

  const onConnect: OnConnect = useCallback(
    (connection: Connection) => {
      setEdges((eds) =>
        addEdge({ ...connection, id: `edge_${Date.now()}`, animated: !!connection.sourceHandle }, eds)
      );
    },
    [setEdges]
  );

  function handleAddNode(type: WorkflowNodeData["nodeType"]) {
    const id = newNodeId();
    const node: FlowNode = {
      id,
      type: "workflowNode",
      position: { x: 120 + Math.random() * 200, y: 120 + Math.random() * 200 },
      data: {
        label:
          type === "trigger" ? "New trigger" : type === "http_request" ? "New request" : "New condition",
        nodeType: type,
        config: {},
      },
    };
    setNodes((nds) => [...nds, node]);
  }

  function handleNodeDataChange(id: string, data: Partial<WorkflowNodeData>) {
    setNodes((nds) => nds.map((n) => (n.id === id ? { ...n, data: { ...n.data, ...data } } : n)));
  }

  function handleDeleteNode(id: string) {
    setNodes((nds) => nds.filter((n) => n.id !== id));
    setEdges((eds) => eds.filter((e) => e.source !== id && e.target !== id));
    setSelectedNodeId(null);
  }

  // A single effect watching the graph's actual state is simpler and more
  // correct than trying to intercept every individual change handler
  // (drag, connect, delete, config edit) to trigger a save: whatever
  // changed, if `nodes`/`edges`/`name` are different, we're dirty and
  // should schedule a save. The `isInitialMount` guard is what stops this
  // from firing (and PATCHing) the instant the editor loads with no real
  // changes yet.
  const isInitialMount = useRef(true);
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    scheduleSave(nodes, edges, name);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nodes, edges, name]);

  return (
    <div className="flex h-screen flex-col">
      <header className="flex items-center justify-between border-b border-border bg-surface px-4 py-3">
        <div className="flex items-center gap-3">
          <Link
            href="/"
            className="flex h-8 w-8 items-center justify-center rounded-md text-text-secondary transition-colors hover:bg-surface-hover hover:text-text-primary"
          >
            <ArrowLeft size={16} />
          </Link>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="bg-transparent font-[family-name:var(--font-display)] text-[15px] font-medium text-text-primary outline-none focus:border-b focus:border-accent-amber"
          />
          <SaveIndicator state={saveState} />
        </div>
        <ExecutionPanel
          workflowId={workflow.id}
          onRunStart={() => {
            // Clear any status rings left over from a previous run before
            // the new run's first step comes in — otherwise a re-run would
            // briefly show stale green/red state from the last execution.
            setNodes((nds) => nds.map((n) => ({ ...n, data: { ...n.data, status: undefined } })));
          }}
          onSteps={(steps: ExecutionStep[]) => {
            const statusByNode = new Map(steps.map((s) => [s.node_id, s.status]));
            setNodes((nds) =>
              nds.map((n) =>
                statusByNode.has(n.id)
                  ? { ...n, data: { ...n.data, status: statusByNode.get(n.id) } }
                  : n
              )
            );
          }}
        />
      </header>

      <div className="flex flex-1 overflow-hidden">
        <NodePalette onAdd={handleAddNode} />

        <div className="flex-1">
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            nodeTypes={nodeTypes}
            onNodeClick={(_, node) => setSelectedNodeId(node.id)}
            onPaneClick={() => setSelectedNodeId(null)}
            colorMode="dark"
            fitView
            proOptions={{ hideAttribution: true }}
          >
            <Background color="var(--color-border)" gap={20} />
            <Controls className="!border !border-border !bg-surface [&>button]:!border-border [&>button]:!bg-surface [&>button]:!fill-text-secondary [&>button]:hover:!bg-surface-hover" />
            <MiniMap
              className="!border !border-border !bg-surface"
              maskColor="rgba(16,19,26,0.7)"
              nodeColor="var(--color-border-strong)"
            />
          </ReactFlow>
        </div>

        {selectedNode && (
          <NodeInspector
            node={selectedNode}
            onChange={handleNodeDataChange}
            onDelete={handleDeleteNode}
            onClose={() => setSelectedNodeId(null)}
          />
        )}
      </div>
    </div>
  );
}

function SaveIndicator({ state }: { state: SaveState }) {
  if (state === "idle") return null;
  const map: Record<Exclude<SaveState, "idle">, { icon: React.ReactNode; text: string; color: string }> = {
    dirty: { icon: <span className="h-1.5 w-1.5 rounded-full bg-text-tertiary" />, text: "Unsaved", color: "text-text-tertiary" },
    saving: { icon: <Loader2 size={12} className="animate-spin" />, text: "Saving…", color: "text-text-tertiary" },
    saved: { icon: <Check size={12} />, text: "Saved", color: "text-accent-teal" },
    error: { icon: <CloudOff size={12} />, text: "Save failed", color: "text-accent-red" },
  };
  const { icon, text, color } = map[state];
  return (
    <span className={`flex items-center gap-1.5 font-mono text-[11px] ${color}`}>
      {icon}
      {text}
    </span>
  );
}
